import { html, css } from 'lit';
import { styleMap } from 'lit/directives/style-map.js';

import formsCss from '@ucd-lib/cork-theme/styles/js/1_base_html/_forms.css.js';
import headerCss from '@ucd-lib/cork-theme/styles/js/4_component/_header.css.js';
import navTrayToggleCss from '@ucd-lib/cork-theme/styles/js/4_component/_nav-tray-toggle.css.js';
import navTrayCss from '@ucd-lib/cork-theme/styles/js/4_component/_nav-tray.css.js';


// Created from styles/images/header-bar1.webp
const defaultBackgroundImage = 'data:image/webp;base64,';

// Created from styles/images/nav-tray-menu-bg.webp
const defaultNavTrayMenuBackgroundImage = 'data:image/webp;base64,';

// Created from styles/images/nav-tray-search-bg.webp
const defaultNavTraySearchBackgroundImage = 'data:image/webp;base64,';

// Created from styles/images/nav-tray-quicklinks-bg2.webp
const defaultNavTrayQuicklinksBackgroundImage = 'data:image/webp;base64,';

// Created from styles/images/nav-tray-quicklinks-bg1.svg
const defaultNavTrayQuicklinksAccentImage = 'data:image/svg+xml;base64,';

/**
 * @description Wraps a URL in a CSS url() value, escaping double quotes.
 * @param {String} url - Image URL or data URI.
 * @returns {String} e.g. 'url("/images/bar.webp")'
 */
function cssUrl(url) {
  return `url("${url.replace(/"/g, '%22')}")`;
}

/**
 * @description Styles for the cork-header element.
 * @returns {Array} Lit css results.
 */
export function styles() {
  const elementStyles = css`
    :host {
      display: block;
    }
    [hidden] {
      display: none !important;
    }
    /* Only the images are overridden, so campus's colors, positions and sizes still apply */
    .nav-tray {
      background-image: var(--nav-tray-menu-bg);
    }
    .nav-tray[data-nav-tray-type="search"] {
      background-image: var(--nav-tray-search-bg);
    }
    .nav-tray[data-nav-tray-type="quicklinks"] {
      background-image: var(--nav-tray-quicklinks-accent-bg), var(--nav-tray-quicklinks-bg);
    }
  `;

  return [
    formsCss,
    headerCss,
    navTrayToggleCss,
    navTrayCss,
    elementStyles
  ];
}

/**
 * @description Main render function for the cork-header element.
 * @returns {TemplateResult}
 */
export function render() {
  const barStyles = {
    backgroundImage: cssUrl(this.backgroundImageUrl || defaultBackgroundImage)
  };
  const navTrayStyles = {
    '--nav-tray-menu-bg': cssUrl(this.navTrayMenuBackgroundImageUrl || defaultNavTrayMenuBackgroundImage),
    '--nav-tray-search-bg': cssUrl(this.navTraySearchBackgroundImageUrl || defaultNavTraySearchBackgroundImage),
    '--nav-tray-quicklinks-bg': cssUrl(this.navTrayQuicklinksBackgroundImageUrl || defaultNavTrayQuicklinksBackgroundImage),
    '--nav-tray-quicklinks-accent-bg': cssUrl(this.navTrayQuicklinksAccentImageUrl || defaultNavTrayQuicklinksAccentImage)
  };
  const toggleButtons = ['primary-nav', 'search', 'quick-links'];

  return html`
  <header class='header'>
    <svg xmlns="http://www.w3.org/2000/svg" style="display:none">
      <symbol id="ucd-logo" viewBox="-12 -1.92 124 20">
        <path fill="currentColor" d="M60.88 4.15c.12.81 1.35 6.63 1.35 6.63h-2.69l1.34-6.63zM50.66 17.68h7.12l.54-2.39h5.08l.68 2.39h7.12L64.53-1.34h-7.47l-6.4 19.02zM33.18-1.34h6.9c6.26 0 11.05 2.79 11.05 9.78 0 5.63-3.9 9.24-9.38 9.24l-8.57-.01V-1.34zm6.77 13.56h.46c2.26 0 3.93-1.32 3.93-3.8 0-2.67-1.48-4.16-3.97-4.16h-.43v7.96zM29.07-.74l.36 3.12c.09.74.52 2.52-.01 2.28-.34-.15-.62-.95-.89-1.67-.14-.36-.81-2.08-.98-2.21-.84-.61-2.95-1.3-4.37-1.31-4.32-.02-7.17 3.08-7.17 8.57 0 3.93 1.94 8.66 6.88 8.66 1.77 0 5.15-.54 6.07-2.99.42-1.1.8-2.09 1.07-1.79.2.22-.06 1.1-.18 1.58-.58 2.27-.61 2.95-.8 3.04-2.23 1.09-5.09 1.45-7.59 1.45-7.95 0-10.7-4.51-10.7-9.02 0-7.83 4.95-11.07 12.62-10.78 1.93.07 3.88.4 5.69 1.07M5.58-.39L4.3-.83c-.43-.37.09-.48.09-.48s1.84.33 6.43-.04c0 0 .4.08.13.39l-1.51.63c-.98.41-.98.17-.98 1.22l-.01 9.69c0 7.58-7.94 7.41-9.48 7.41-.74 0-7.96 0-7.96-6.09V1.65c0-1.79.19-1.74-.41-1.95l-1.84-.67s-.31-.43.24-.4c1.51.07 3.68.39 8.75.03 0 0 .44.1.15.42l-1.47.42C-4.74.01-4.58-.38-4.61.78l.03 10.12c0 2.48 1.31 5.55 5.39 5.55 5.62 0 5.68-4.73 5.68-5.78L6.5.64c.06-.95-.07-.68-.92-1.03M96.18 16.22l1.96-5.04.34.28c1.21.96 2.84 1.77 4.39 1.8 1.38.03 2.05-.33 1.87-1.46-.14-.85-1.12-1-1.74-1.12l-1.35-.26c-2.63-.48-4.84-2.05-4.84-5.03 0-4.51 4-7.04 8.03-7.04 2.12 0 4.05.52 5.87 1.67L109 4.49c-.94-.65-2.35-1.58-4.14-1.64-.59-.02-1.94.28-1.51 1.61.19.57 1.02.81 1.54.93l1.52.36c2.85.65 4.91 2.22 4.91 5.44 0 4.54-4.03 6.78-8.02 6.78-2.32 0-5.03-.65-7.12-1.75M88-1.34h6.74v19.02H88zM80.28-1.34h7.01l-7.16 19.02h-5.7L67.28-1.34h7l3 11.48z"></path>
      </symbol>
    </svg>
    <div class="header__bar" style=${styleMap(barStyles)}>
      <div class="header__university">
        <a href="https://www.ucdavis.edu/" aria-label="UC Davis homepage">
          <svg class="ucd-logo" width="124" height="20" aria-hidden="true">
            <use href="#ucd-logo"></use>
          </svg>
        </a>
      </div>
      <div class="header__toggles">
        ${toggleButtons.map(buttonName => _renderToggleButton.call(this, buttonName))}
      </div>
    </div>
    <dialog class="nav-tray" aria-label="Navigation Tray" style=${styleMap(navTrayStyles)}>
      <div class="nav-tray__inner">
        <div class="nav-tray__bar">
          <div class="nav-tray__logo">
            <a href="https://www.ucdavis.edu/" aria-label="UC Davis homepage">
              <svg class="ucd-logo" width="124" height="20" aria-hidden="true">
                <use href="#ucd-logo"></use>
              </svg>
            </a>
          </div>
          <div class="nav-tray__title">${this._selectedNavComponent?.label || ''}</div>
          <div class="nav-tray__toggles">
            ${toggleButtons.map(buttonName => _renderToggleButton.call(this, buttonName))}
          </div>
        </div>

        <div id="nav-tray-menu" class="nav-tray__content nav-tray__content--menu">
          <slot name="primary-nav"></slot>
        </div>
        <div id="nav-tray-search" class="nav-tray__content nav-tray__content--search">
          <slot name="search"></slot>
        </div>
        <div id="nav-tray-quicklinks" class="nav-tray__content nav-tray__content--quicklinks">
          <slot name="quick-links"></slot>
        </div>

      </div>
    </dialog>

  </header>

  `;

/**
 * Renders a toggle button for a navigation component if the slotted component exists.
 * @param {String} componentName - The name of the component from this._slottedComponents
 * @returns {TemplateResult} 
 */
  function _renderToggleButton(componentName){
    const component = Object.values(this._slottedComponents).find(c => c.name === componentName);
    if (  !component?.ele ) return html``;
    const isSelected = this._selectedNavComponent?.name === component.name;

    return html`
      <button
        data-toggle=${component.navTrayName}
        class="nav-tray-toggle nav-tray-toggle--${component.navTrayName}"
        aria-controls="nav-tray-${component.navTrayName}"
        aria-expanded=${isSelected}
        aria-label="${isSelected ? 'Close' : 'Open'} ${component.label} tray"
        @click=${() => this._onToggleButtonClick(component)}
      >
      </button>
    `;
  }
}